fn with_id_expr_uses_time_or_random(e: &HirExpr) -> Option<String> {
    use HirExpr::*;
    match e {
        MethodCall(obj, method, _, _, _) => {
            if let Ident(module, _) = obj.as_ref() {
                if matches!(module.as_str(), "time" | "clock" | "random") {
                    return Some(format!("{module}.{method}"));
