                let store = crate::bundle::BundleStore::open(self.root.clone()).ok()?;
                store.lookup(&crate::bundle::BundleRef { fn_hash: *fn_hash }).ok().flatten()
            }
            CacheLookup::Miss { .. } => None,
        }
    }
